#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    long long n;
    cin >> n;

    while (n >= 10) {
        long long total = 0;
        while (n > 0) {
            total += n % 10;
            n /= 10;
        }
        n = total;
    }
    cout << n << endl;

    return 0;
}

code.java:
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();

        while (n >= 10) {
            long total = 0;
            while (n > 0) {
                total += n % 10;
                n /= 10;
            }
            n = total;
        }
        System.out.println(n);
    }
}
